    "「不。真錯了就得拉住我，別讓我越走越遠。」": "\"No. If you're really wrong, you have to hold me back and don't let me go further.\"",
    "「不太擅長。我習慣先照顧別人，輪到自己就會忘記怎麼開口。」": "\"I'm not very good at it. I'm used to taking care of others first, and I forget how to speak when it's my turn.\"",
    "「不用。留一點光。」": "\"No need. Leave some light.\"",
