    "「不用把我當易碎品。但……有人注意，確實不壞。」": "\"You don't need to treat me as fragile. But...someone pays attention to it, so it's really not bad.\"",
    "「不怕黑。我怕的是黑暗裡有需要幫忙的人，我卻沒看見。」": "\"I'm not afraid of the dark. What I'm afraid of is that there are people in need of help in the dark, but I don't see them.\"",
    "「不知道說什麼。會放水、拿吃的、待在旁邊。」": "\"I don't know what to say. I can put water, get food, and stay by my side.\"",
