    "「不是血緣才算。會回來、會留位置，就是。」": "\"It's not about blood. It's about coming back and leaving a place.\"",
    "「不是盲目保密，而是先為對方著想。這答案很好。」": "\"It's not about keeping secrets blindly, but thinking about the other person first. That's a good answer.\"",
