    "確定要清除目前進度嗎？": "Are you sure you want to erase your current progress?",
    "練習結束後，Nyx 沒像平常一樣立刻離開。她坐在場邊，問你是否有過明知不該、卻無法停止的感情。": "After practice, Nyx didn't leave immediately like usual. She sits on the sidelines and asks you if you've ever had feelings that you knew you shouldn't have but couldn't stop.",
    "談Asteria的邀約": "Talking about Asteria’s invitation",
    "請她下次推薦一首。": "Ask her to recommend a song for next time.",
    "請她安靜待在身邊。": "Ask her to stay quietly.",
    "請她教自己基礎動作。": "Ask her to teach you basic moves.",
    "請她說一句真心話": "Ask her to tell the truth",
