    "點擊角色卡片切換房間，點擊角色或選項開始對話。": "Select a character card to visit their room, then click the character or choose a response to talk.",
    "離開前，她替你整理被風吹亂的衣領。「今天很愉快。下次，不用等我邀請。」": "Before leaving, she tidied your collar that was messed up by the wind. \"I had a great time today. Next time, don't wait for my invitation.\"",
    "離開時她把戰績小票折好收進口袋。「第一次一起打。要留著。」": "When she left, she folded the winning ticket and put it in her pocket. \"This is the first time we fight together. Keep it.\"",
