    "競爭時會不會放水": "Will you give in when competing?",
    "覺得清者自清。": "He who feels pure will become pure himself.",
    "攤位快收攤時，她把最後一份熱食塞進你手裡，自己只喝了水。你分她一半，她愣了愣，痛快地笑出聲。": "When the stall was about to close, she put the last piece of hot food into your hand and drank only water. You gave her half, she was stunned and laughed happily.",
    "驚": "surprised",
    "驚訝她記得。": "Surprised she remembered.",
    "Asteria 把書闔上。「你今天看起來有些疲倦。工作很多嗎？」": "Asteria closed the book. \"You look a little tired today. Have you had a lot of work?\"",
    "Asteria 承認自己害怕失去，也害怕開口挽留會顯得脆弱。你告訴她，想留下不是因為被挽留，而是因為選擇她。": "Asteria admitted that she was afraid of losing, and that she was afraid of appearing vulnerable if she opened her mouth to try to stay. You tell her that you want to stay not because you were asked to stay, but because you chose her.",
    "Asteria 看著你驚訝的表情，愉快地承認：「偶爾讓我使點壞心眼，不行嗎？」": "Asteria looked at your surprised expression and admitted happily: \"Can't you let me be a little mean sometimes?\"",
    "Asteria 約你到窗邊的小茶館。她沒有替你點餐，只把菜單推過來，認真聽你挑選。": "Asteria invites you to the small teahouse by the window. She didn't order for you, she just pushed the menu over and listened carefully to your selection.",
    "Asteria 眨了眨眼。「這次換我不知道該怎麼接了。」": "Asteria blinked. \"I don't know how to handle it this time.\"",
    "Asteria 靠近一些。「有句話我練習了很多次，可每次看見你就說不完整。」": "Asteria moves closer. \"I have practiced a sentence many times, but every time I see you I can't say it completely.\"",
    "Lumi 把一把備用鑰匙放到你掌心。「拿著。」": "Lumi places a spare key in the palm of your hand. \"Take it.\"",
    "Lumi 把另一支手把推過來。「玩嗎？」": "Lumi pushed the other hand over. \"Want to play?\"",
    "Lumi 看了你一眼。「手很冷？」": "Lumi glanced at you. \"Are your hands cold?\"",
    "Lumi 看了看你和她之間的空位。「那邊看得到嗎？」": "Lumi looked at the space between you and her. \"Can you see it over there?\"",
    "Lumi 約你回到房間，桌上放著她第一次學做的便當。煎蛋有一點焦，但每樣都是你喜歡的味道。": "Lumi invites you back to the room, where the bento she first learned to make is on the table. The fried eggs are a little burnt, but everything tastes like you like.",
    "Lumi 帶你去她熟悉的遊戲中心，替你選了一台按鍵狀況最好的機台。": "Lumi takes you to a game center she is familiar with and chooses a machine with the best buttons for you.",
    "Lumi 默默把水放到你旁邊。「慢點。」": "Lumi silently placed the water next to you. \"Slow down.\"",
    "Lumi 難得沒有穿斗篷，只穿著輕便的白色衣裝。她說是因為今天不需要警戒。": "Lumi is rarely seen without a cape, wearing only light white clothing. She said it was because there was no need to be vigilant today.",
    "Nyx 低著頭很久，最後長長吐出一口氣：「謝了。至少在你面前，我不用假裝這件事不存在。」": "Nyx lowered his head for a long time, and finally exhaled a long breath: \"Thank you. At least in front of you, I don't have to pretend that this matter doesn't exist.\"",
    "Nyx 咧嘴一笑。「好。那你的背後也交給我。」": "Nyx grinned. \"Okay. Then leave your back to me.\"",
    "Nyx 握緊手指。「想。也怕。她若知道，可能連現在都保不住。」": "Nyx clenched her fingers. \"I want to. I'm also afraid. If she knew, she might not be able to survive even now.\"",
    "Nyx 說要帶你去吃真正好吃的街頭料理，結果一路上停下來幫了三次忙。": "Nyx said he was going to take you to eat some really good street food, and ended up stopping three times to help out along the way.",
    "Nyx 皺起眉。「別拿這種事開玩笑。」": "Nyx frowned. \"Don't joke about this.\"",
    "Nyx 邀你陪她走一段平常巡視的路。她一路記住壞掉的路燈，也確認獨居老人家的門窗。": "Nyx invites you to accompany her on some of her usual rounds. Along the way, she memorized the broken street lights and also identified the doors and windows of the old man's house who lived alone.",
