    "吃完後，她把備用鑰匙放進你手裡。她沒有長篇解釋，只說這裡不再需要把你當客人。": "吃完後，她把備用鑰匙放進你手裡。她沒有長篇解釋，只說這裡不再需要把你當客人。",
    "向她借充電線。": "向她借充電線。",
    "向重要的人說明，其他人不勉強。": "向重要的人說明，其他人不勉強。",
    "回程她說：「下次得早點出門。不是為了吃，是因為跟你一起繞路也挺有意思。」": "回程她說：「下次得早點出門。不是為了吃，是因為跟你一起繞路也挺有意思。」",
    "回程時她把選擇交還給你。你牽起她的手，帶她走上一條沒有安排過的路。她笑得比整天任何時候都真。": "回程時她把選擇交還給你。你牽起她的手，帶她走上一條沒有安排過的路。她笑得比整天任何時候都真。",
