    "回想": "回想",
    "她小聲說出一個簡短暱稱。「……可以嗎？」": "她小聲說出一個簡短暱稱。「……可以嗎？」",
    "她仍微笑著。「這個願望，我不建議你實現。」": "她仍微笑著。「這個願望，我不建議你實現。」",
    "她立刻打開重播。「看第三回合。」": "她立刻打開重播。「看第三回合。」",
    "她立刻遞過來。「下次早點充。」": "她立刻遞過來。「下次早點充。」",
    "她向你伸出拳頭：「戀愛那些我可能永遠搞不明白。但你是我選的搭檔，這件事不會變。」": "她向你伸出拳頭：「戀愛那些我可能永遠搞不明白。但你是我選的搭檔，這件事不會變。」",
    "她回握住你。「嗯。現在這樣，就足夠了。」": "她回握住你。「嗯。現在這樣，就足夠了。」",
    "她在你旁邊坐下，把音量調低。「要說嗎？」": "她在你旁邊坐下，把音量調低。「要說嗎？」",
    "她安靜了一瞬。「你這句話，比安慰更讓人安心。」": "她安靜了一瞬。「你這句話，比安慰更讓人安心。」",
    "她耳尖泛紅，視線仍盯著螢幕。「……看比賽。」": "她耳尖泛紅，視線仍盯著螢幕。「……看比賽。」",
    "她低下頭。「那輸了也……不會只剩我一個。」": "她低下頭。「那輸了也……不會只剩我一個。」",
    "她低頭看著手把。「……那就好。」": "她低頭看著手把。「……那就好。」",
    "她冷靜指出對方的行為並叫來支援，直到事情完全結束才轉身檢查你是否受傷。": "她冷靜指出對方的行為並叫來支援，直到事情完全結束才轉身檢查你是否受傷。",
    "她別開視線。「你故意挑最犯規的叫法，對吧？」": "她別開視線。「你故意挑最犯規的叫法，對吧？」",
    "她告訴你，自己總習慣成為照顧別人的人，久而久之，連疲倦都不知道該向誰承認。": "她告訴你，自己總習慣成為照顧別人的人，久而久之，連疲倦都不知道該向誰承認。",
    "她把一罐飲料遞來。「你常喝這個。」": "她把一罐飲料遞來。「你常喝這個。」",
    "她把比較完整的煎蛋夾給你。「這個沒焦。」": "她把比較完整的煎蛋夾給你。「這個沒焦。」",
    "她把行動電源塞給你。「下次帶著。我有多的。」": "她把行動電源塞給你。「下次帶著。我有多的。」",
    "她把茶遞給你。「這個比較好。」": "她把茶遞給你。「這個比較好。」",
    "她把排名畫面轉過來。「上去了。」": "她把排名畫面轉過來。「上去了。」",
    "她把暖暖包放進你手裡。「拿著。」": "她把暖暖包放進你手裡。「拿著。」",
    "她把螢幕轉向你。「這樣。」": "她把螢幕轉向你。「這樣。」",
    "她沉默了一會兒。「……因為擔心。」": "她沉默了一會兒。「……因為擔心。」",
    "她沉默片刻。「你不在的時候，我會覺得這個房間太安靜。」": "她沉默片刻。「你不在的時候，我會覺得這個房間太安靜。」",
    "她沉默幾秒。「我在外面。需要就叫我。」": "她沉默幾秒。「我在外面。需要就叫我。」",
    "她沒有打斷，最後只說：「我在。」": "她沒有打斷，最後只說：「我在。」",
    "她沒有放水，卻在每回合後指出一個最需要改的地方。你終於贏下一局時，她沒有懊惱，只是立刻投下下一枚代幣。": "她沒有放水，卻在每回合後指出一個最需要改的地方。你終於贏下一局時，她沒有懊惱，只是立刻投下下一枚代幣。",
    "她沒有說出名字，但你已經明白。你沒有追問，只告訴她感情本身並不是罪，也不必為此否定自己。": "她沒有說出名字，但你已經明白。你沒有追問，只告訴她感情本身並不是罪，也不必為此否定自己。",
    "她垂下眼。「想保護的人受傷。」": "她垂下眼。「想保護的人受傷。」",
    "她往後退了一步。「先問。」": "她往後退了一步。「先問。」",
    "她肩膀放鬆下來。「這樣就好。」": "她肩膀放鬆下來。「這樣就好。」",
    "她指著兩張海報。「動作片。紀錄片。」": "她指著兩張海報。「動作片。紀錄片。」",
    "她按住口袋。「不行。」": "她按住口袋。「不行。」",
    "她看向窗外大雨。「你沒帶傘。」": "她看向窗外大雨。「你沒帶傘。」",
    "她看見你的電量。「剩五趴。」": "她看見你的電量。「剩五趴。」",
    "她看著你。「已經算。」": "她看著你。「已經算。」",
    "她眨了眨眼。「……那就好。」": "她眨了眨眼。「……那就好。」",
    "她笑得更溫柔了。「你確定？」": "她笑得更溫柔了。「你確定？」",
