    "你今天不太專心": "你今天不太专心",
    "你以為今天由自己規劃，卻發現預約、交通和你喜歡的餐點都已被她悄悄準備好。": "你以为今天由自己规划，却发现预约、交通和你喜欢的餐点都已被她悄悄准备好。",
    "你收下鑰匙。Lumi 靠到你肩邊，小聲補上一句：「回來的時候，說一聲。我會等。」": "你收下钥匙。 Lumi 靠到你肩边，小声补上一句：「回来的时候，说一声。我会等。」",
    "你告訴她，守護不必是一個人的工作。她伸出拳頭：「那就一起。說好了。」": "你告诉她，守护不必是一个人的工作。她伸出拳头：「那就一起。说好了。」",
    "你坐得太遠": "你坐得太远",
    "你忘記帶傘": "你忘记带伞",
    "你沒有急著安慰，只陪她看完月亮。離開時，她主動握住你的手：「今晚，謝謝你沒有讓我一個人。」": "你没有急着安慰，只陪她看完月亮。离开时，她主动握住你的手：「今晚，谢谢你没有让我一个人。」",
    "你和別人發生衝突": "你和别人发生冲突",
    "你很晚才回來": "你很晚才回来",
    "你是否害怕改變關係": "你是否害怕改变关系",
    "你們一起買日用品、吃簡單的午餐，再回房間整理遊戲收藏。沒有大事件，她卻一直待在你伸手可及的位置。": "你们一起买日用品、吃简单的午餐，再回房间整理游戏收藏。没有大事件，她却一直待在你伸手可及的位置。",
    "你們在遊戲中心比賽。Nyx 一開始不熟操作，卻拒絕讓你放水。": "你们在游戏中心比赛。 Nyx 一开始不熟操作，却拒绝让你放水。",
    "你們為了挑戰雙人模式的最高分，從傍晚一路打到店員提醒即將打烊。": "你们为了挑战双人模式的最高分，从傍晚一路打到店员提醒即将打烊。",
