    "事件回想": "事件回想",
    "事情結束後，你們渾身濕透，坐在屋簷下分享一條毛巾。Nyx 看著狼狽的你，忽然笑得停不下來。": "事情结束后，你们浑身湿透，坐在屋檐下分享一条毛巾。 Nyx 看着狼狈的你，忽然笑得停不下来。",
