    "離開前，她替你整理被風吹亂的衣領。「今天很愉快。下次，不用等我邀請。」": "离开前，她替你整理被风吹乱的衣领。 「今天很愉快。下次，不用等我邀请。」",
    "離開時她把戰績小票折好收進口袋。「第一次一起打。要留著。」": "离开时她把战绩小票折好收进口袋。 「第一次一起打。要留着。」",
