    "攤位快收攤時，她把最後一份熱食塞進你手裡，自己只喝了水。你分她一半，她愣了愣，痛快地笑出聲。": "摊位快收摊时，她把最后一份热食塞进你手里，自己只喝了水。你分她一半，她愣了愣，痛快地笑出声。",
