    "問那個人是誰。": "その人が誰なのか尋ねる。",
    "問那個未來裡有沒有自己。": "あなたがその未来にいるかどうか自問する。",
    "問是不是Asteria挑的。": "アステリアがそれを選んだかと尋ねた。",
    "問哪一樣最重要。": "どれが最も重要かを尋ねる。",
    "問能不能一起走。": "一緒に行ってもいいかと尋ねられました。",
    "問能不能坐旁邊看。": "座って見てもいいですかと尋ねる。",
    "問能不能翻她的口袋。": "彼女のポケットを調べてもいいですかと尋ねた。",
    "問這也需要陪嗎。": "ここにも仲間が必要かどうか尋ねる。",
    "問這些擺設花了多少錢。": "装飾品にどれくらいの費用がかかるか聞く。",
    "問普通是幾分。": "正常なスコアが何であるかを尋ねます。",
