    "密技啟動！三位角色好感度與所有回想已解鎖": "隠しコマンド発動！ 3人の好感度と思い出をすべて解放しました。",
    "專屬稱呼": "独占タイトル",
    "接過手把，請她教自己。": "コントローラーを握り、彼女に教えてくれるよう頼んだ。",
    "接過耳機，安靜聽完。": "ヘッドフォンを手に取り、静かに聞く。",
    "接過茶杯，小口品嚐。": "ティーカップを取り、一口飲みました。",
    "推薦節奏明快的動作遊戲。": "テンポの速いアクションゲームにおすすめです。",
    "推薦慢節奏戀愛遊戲。": "スローペースな恋愛ゲームがおすすめ。",
    "推薦遠距離角色。": "遠距離キャラにおすすめ。",
    "清脆一聲後，她嘴角揚起。「下一個目標，更高。」": "ぱりぱりと音を立てた後、彼女の口角が上がった。 「次の目標はもっと高いところにある。」",
    "猜她只是想捉弄自己。": "彼女はただ自分をからかいたかっただけだと思います。",
    "猜她喜歡黑咖啡。": "彼女はブラックコーヒーが好きだと思います。",
    "猜床上。": "ベッドを推測してください。",
    "猜拳決定座位": "席を推測してください",
    "猜窗邊的椅子。": "窓のそばの椅子を推測してください。",
    "甜點二選一": "デザートの選択",
    "甜點送來後，她自然地把草莓留給你。你問起原因，她笑著說：「因為你看它第三次了。」": "デザートが来ると、当然のようにイチゴを残してくれます。理由を尋ねると、彼女は微笑んで「3回目だから」と言いました。",
    "羞": "恥ずかしがり屋",
    "途中你問她為何總把別人的安全放在前面。她沉默片刻，承認自己害怕來不及。": "途中、あなたは彼女に、なぜ彼女はいつも他人の安全を最優先するのかと尋ねました。彼女はしばらく沈黙し、手遅れになるのではないかと心配していたことを認めた。",
    "逞強說完全不辣。": "あえて言いますが、全然辛くないです。",
    "連輸幾局後，她仔細觀察你的節奏，終於在最後一回合逆轉。她高興得差點把你抱離地面。": "数試合連続で負けた後、彼女はあなたのリズムを注意深く観察し、最終ラウンドでついに逆転しました。彼女はとても嬉しかったので、あなたを地面から持ち上げてしまいそうになりました。",
    "最好的搭檔": "最高のパートナー",
    "最後一關失敗時，Lumi 盯著畫面很久。你以為她不甘心，她卻先確認你累不累。": "最後のレベルに失敗したとき、ルミは長い間画面を見つめていました。彼女は折れる気はないと思いますが、彼女はまずあなたが疲れているかどうかを確認します。",
    "喔，你來啦。今天過得怎樣？": "お、来たね。今日はどうだった？",
    "喜": "幸せな",
    "喝哪一罐": "どの缶を飲もう？",
    "握住她的手，說自己還在。": "彼女の手を握って、あなたはまだここにいると伝える。",
    "替你留晚餐": "夕食を自分のために取っておく",
    "發現你隱瞞受傷": "怪我を隠していたことが発覚",
    "窗戶是否太亮": "窓が明るすぎませんか？",
    "答應，但也要她願意回頭。": "同意しますが、彼女は喜んで振り返るでしょう。",
    "答應，並先問Asteria最近缺什麼。": "同意し、まずアステリアに最近何が足りないのか尋ねます。",
    "答應，順便一起補齊日用品。": "同意します、日用品を一緒に補いましょう。",
    "答應一定親口告訴她，也會保持聯絡。": "彼女に個人的に伝え、連絡を取り続けることを約束する。",
    "答應並請她說明想測什麼。": "「はい」と答えて、何をテストしたいのか説明してもらいます。",
    "答應和她互相照應。": "彼女とお互いを大事にすることを約束する。",
    "答應會認真寫一封。": "手紙は注意深く書くことを約束する。",
    "答應準時出現。": "時間通りに来ると約束する。",
    "結帳後你才發現，她也買了一枚與你外套同色的小飾品。她只說那是巧合。": "チェックアウト後、彼女があなたのコートと同じ色の小さな装飾品も購入したことに気づきました。彼女はただ偶然だと言いました。",
    "給你看最高排名": "最高のランキングを表示します",
    "街頭補給": "街頭用品",
    "開始對話": "話しかける",
    "開玩笑說她特別在意Asteria。": "アステリアのことを気にかけていると冗談めかして言う。",
    "開玩笑說她終於坦白了。": "彼女がついに潔白になったと冗談を言いました。",
    "開玩笑說想見識看看。": "それを見たいと冗談を言った。",
    "開啟背景音樂": "BGMをオンにする",
    "開啟音效": "効果音をオンにする",
    "想一起完成的事": "一緒に達成したいこと",
    "想一起挑禮物": "一緒にプレゼントを選びたい",
    "想一起買生活用品": "日用品をまとめて買いたい",
