    "想向你借東西": "あなたから何か借りたいのですが",
    "想收到的禮物": "受け取りたいプレゼント",
    "想住的地方": "住みたい場所",
    "想請你幫忙": "あなたの助けが欲しい",
    "搬張椅子坐到她旁邊。": "椅子を引いて彼女の隣に座る。",
    "新的回想已解鎖": "新しい思い出が解放されました。",
    "會不會替朋友出頭": "友達のために立ち上がりますか？",
    "會生氣，但更想知道他為何不敢說。": "私は怒るでしょうが、なぜ彼があえて何も言わないのかも知りたいです。",
    "會向重要的人說清楚。": "大切な人にわかりやすく伝えます。",
    "遇到插隊會怎麼做": "行列が切断されたらどうしますか?",
    "道歉並答應有變動會先說。": "謝罪し、変更があればお知らせすることを約束します。",
    "察覺你心情不佳": "あなたが機嫌が悪いことに気づきました",
    "對失敗的看法": "失敗に対する視点",
    "對她的第一印象": "彼女の第一印象",
    "對你的信任": "あなたを信頼してください",
    "稱讚她準備得很齊全。": "彼女がよく準備をしていることを褒めてください。",
    "稱讚房間的擺設": "部屋の設備を褒める",
    "認真和她猜拳。": "彼女と真剣に推理ゲームをしてみましょう。",
    "說一定自己搬。": "自分で動かすと伝える。",
